def main():
    if len(sys.argv) > 2:
        raise RuntimeError("Usage: bash pull.sh [Macchiato installation folder]")
    root = Path(sys.argv[1] if len(sys.argv) == 2 else os.getcwd()).resolve()
    if not (root / "webloom.py").is_file() or not (root / "server").is_dir() or not (root / "public").is_dir():
        raise RuntimeError("Run this from your existing Macchiato folder, or pass that folder as its argument.")

    raw = base64.b64decode(PAYLOAD)
    if hashlib.sha256(raw).hexdigest() != DIGEST:
        raise RuntimeError("Update checksum failed. No files were changed.")
    entries = []
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        seen = set()
        for entry in archive.infolist():
            name = PurePosixPath(entry.filename)
            if (name.is_absolute() or ".." in name.parts or not name.parts or
                    any(part.startswith(".") or part == "__pycache__" for part in name.parts) or
                    entry.filename in seen or entry.is_dir() or
                    stat.S_ISLNK(entry.external_attr >> 16)):
                raise RuntimeError("Invalid file in update archive.")
            if entry.filename not in ("webloom.py", "README.md") and name.parts[0] not in ("server", "public", "native"):
                raise RuntimeError("Update contains files outside the application code.")
            seen.add(entry.filename)
            destination = root.joinpath(*name.parts)
            # Refuse symlinks instead of following them outside the installation.
            cursor = root
            for part in name.parts:
                cursor = cursor / part
                if cursor.is_symlink():
                    raise RuntimeError("Update target contains a symlink: " + str(name))
            if destination.exists() and not destination.is_file():
                raise RuntimeError("Update target is not a regular file: " + str(name))
            content = archive.read(entry)
            if name.suffix == ".py":
                compile(content, str(name), "exec")
            mode = 0o755 if (entry.external_attr >> 16) & 0o111 else 0o644
            entries.append((entry.filename, destination, content, mode))
    if not {"webloom.py", "server/app.py", "public/index.html", "native/WebloomBrowser.swift"}.issubset(seen):
        raise RuntimeError("The update is missing required application files.")

    os.umask(0o077)
    backup_dir = Path(os.environ.get("MACCHIATO_UPDATE_BACKUP_DIR", str(
        Path.home() / "Library" / "Application Support" / "webloom" / "update-backups")))
    backup_dir.mkdir(parents=True, exist_ok=True, mode=0o700)
    timestamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    fd, backup_name = tempfile.mkstemp(prefix="before-" + VERSION + "-" + timestamp + "-", suffix=".zip", dir=backup_dir)
    originals = {}
    with os.fdopen(fd, "w+b") as output, zipfile.ZipFile(output, "w", zipfile.ZIP_DEFLATED) as backup:
        for name, destination, _, _ in entries:
            if destination.exists():
                originals[name] = (destination.read_bytes(), stat.S_IMODE(destination.stat().st_mode))
                backup.writestr(name, originals[name][0])
        backup.writestr("update-manifest.json", json.dumps({
            "installation": str(root), "update": VERSION,
            "created": [name for name, _, _, _ in entries if name not in originals],
            "original_modes": {name: mode for name, (_, mode) in originals.items()},
        }, indent=2))

    def replace(destination, content, mode):
        destination.parent.mkdir(parents=True, exist_ok=True)
        fd, temporary = tempfile.mkstemp(prefix=".macchiato-update-", dir=destination.parent)
        try:
            with os.fdopen(fd, "wb") as output:
                output.write(content)
                output.flush()
                os.fsync(output.fileno())
            os.chmod(temporary, mode)
            os.replace(temporary, destination)
        finally:
            if os.path.exists(temporary):
                os.unlink(temporary)

    applied = []
    try:
        for name, destination, content, mode in entries:
            replace(destination, content, mode)
            applied.append((name, destination))
    except BaseException:
        for name, destination in reversed(applied):
            if name in originals:
                replace(destination, *originals[name])
            else:
                destination.unlink()
        print("Installation failed; applied files were rolled back. Backup: " + backup_name, file=sys.stderr)
        raise
    print("Installed full Macchiato update " + VERSION + " (" + str(len(entries)) + " files).")
    print("Previous code backup: " + backup_name)
    print("Saved cookies, workspaces, preferences and pullversion were preserved.")
    print("Restart Macchiato, then reload its browser page to use the update.")

try:
    main()
except Exception as error:
    print("Macchiato update failed: " + str(error), file=sys.stderr)
    sys.exit(1)

MACCHIATO_UPDATE_PY
